class MyContainerPackable implements SysPackable
{
    str itemName;
    int qty;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
    itemName,
    qty
    #endmacro

}

Method.Source:
public static MyContainerPackable construct(str _itemName, int _qty)
{
    MyContainerPackable packable = new MyContainerPackable();

    packable.parmItemName(_itemName);
    packable.parmQty(_qty);

    return packable;
}

public str parmItemName(str _itemName = itemName)
{
    itemName = _itemName;

    return itemName;
}

public int parmQty(int _qty = qty)
{
    qty = _qty;

    return qty;
}

/// <summary>
/// Saves the state into a container. The version number goes first.
/// </summary>
public container pack()
{
    return [#CurrentVersion, #CurrentList];
}

/// <summary>
/// Restores the state from a container. Returns false if the version is unknown.
/// </summary>
public boolean unpack(container _packedClass)
{
    int version = conPeek(_packedClass, 1);

    switch (version)
    {
        case #CurrentVersion:
            [version, #CurrentList] = _packedClass;
            break;

        default:
            return false;
    }

    return true;
}
